    t=t.replace("ШІкарно","Шікарно")
    R=[("Turn off and delete activity","Терн офф енд деліт актівіті"),("Settings and help","Сеттінгс енд хелп"),("Privacy Center","Прайвасі Сентер"),("Claude for Work","Клод фор Ворк"),("Claude Meetings","Клод Мітінгс"),("Microsoft 365","Майкрософт триста шістдесят п'ять"),("Business","Бізнес"),("Enterprise","Ентерпрайз"),("API","Ей-Пі-Ай"),("Short","Шорт"),("Improve the model for everyone","Імпрув зе модел фор еврівань"),("Help improve Claude","Хелп імпрув Клод"),("Training on conversation activity","Трейнінг он конверсейшн актівіті"),
       ("Training on voice conversations","Трейнінг он войс конверсейшнз"),("Delete all Memory","Деліт ол меморі"),("Manage memories","Менедж меморіз"),("Personal Intelligence","Персонал Інтеліджнс"),
       ("Keep Activity","Кіп Актівіті"),("Settings & help","Сеттінгс енд хелп"),("Data controls","Дейта контролз"),("Temporary Chat","Темпорарі чат"),("Personalization","Персоналізейшн"),
       ("Ads Preferences","Едс Преференсіз"),("Accounts Center","Акаунтс Сентер"),("Turn off","Терн офф"),("Settings","Сеттінгс"),("Privacy","Прайвасі"),("Memory","Меморі"),("Activity","Актівіті"),
       ("Personal Finance","Персонал Файненс"),("Google Meet","Гугл Міт"),("Meta AI","Мета Ей-Ай"),("WhatsApp","Вотсап"),("Instagram","Інстаграм"),("Facebook","Фейсбук"),("Messenger","Месенджер"),
       ("ChatGPT","Чат Джі-Пі-Ті"),("OpenAI","Оупен Ей-Ай"),("Gemini Live","Джеміні Лайв"),("Gemini","Джеміні"),("Google","Гугл"),("Claude","Клод"),("Anthropic","Антропік"),
       ("Copilot","Копайлот"),("Microsoft","Майкрософт"),("Windows","Віндовс"),("Bing","Бінг"),("Gems","Джемз"),("skills","скілз"),("Plaid","Плейд"),("Meta","Мета"),
       ("Personal","Персонал"),("Family","Фемілі"),("Free","Фрі"),("Plus","Плас"),("Pro","Про"),("2FA","двофакторної автентифікації"),("SMS","есемес"),("CVV","сі-ві-ві"),("РНОКПП","податковий номер")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    return t.replace("ШІ","штучний інтелект")

