def _pack(lim=2200):
    P=[];cur=[];n=0
    for i,x in enumerate(SEGS):
        L=len(G(x["text"]))
        if cur and n+L>lim: P.append(cur); cur=[]; n=0
        cur.append(i); n+=L
    P.append(cur); return P
PARTS=_pack()

